 ICON.peLatch=(x,y)=>`<g transform="translate(${x-210} ${y-165})"><rect x="-14" y="10" width="448" height="320" rx="18" fill="#FFF4E6"/>${PE_scr(150,170,2.2,ORG)}${PE_T(330,110,'latched',{fs:34,fw:800,a:'middle',fill:ORG})}${PE_T(330,190,'gate off:',{fs:30,fw:700,a:'middle',fill:PE_MUT})}${PE_T(330,234,'still on',{fs:34,fw:800,a:'middle',fill:ORG})}</g>`;
 ICON.peTrig=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${PE_L(10,200,410,200,PE_AX,2)}${[0,1,2].map(k=>PE_curve(PE_vC,0,0.988,20+k*130,140+k*130,200,8,GRN,5,40)+PE_L(140+k*130,93.6,140+k*130,184,GRN,3)).join('')}${PE_L(10,300,410,300,PE_AX,2)}${[0,1,2].map(k=>PE_poly([[134+k*130,300],[140+k*130,240],[148+k*130,300]],GRN,5)).join('')}${PE_T(210,40,'charge, fire, pulse',{fs:28,fw:800,a:'middle',fill:GRN})}</g>`;
